 [pscustomobject]@{itemId='4fe9f411-09bc-443d-9c15-a1d266bcb825';reference='235089532797';part='55280-2T000';compactPart='552802T000';categoryId='262227';usd='151.76';shipping='7day fast';title='⭐Genuine 552802T000 Rear Trailing Arm RH For Kia Optima 2011-2016';partWords='rear trailing arm right';usStores=@('13146861012');auStores=@('/Kia/Optima');auTargets=@(@{make='Kia';model='Optima';minYear=2011;maxYear=2016;enginePattern=$petrolHybrid})},
 [pscustomobject]@{itemId='f57e6f80-b4f1-4af8-afe8-020cb98c379b';reference='156794019486';part='55270-2T000';compactPart='552702T000';categoryId='33580';usd='151.76';shipping='7day fast';title='⭐Genuine 552702T000 Rear Trailing Arm LH For Kia Optima 2011-2016';partWords='rear trailing arm left';usStores=@('13146861012');auStores=@('/Kia/Optima');auTargets=@(@{make='Kia';model='Optima';minYear=2011;maxYear=2016;enginePattern=$petrolHybrid})},
