 [pscustomobject]@{itemId='954dd957-e171-4c3c-a928-4f72044d69d8';reference='257683988425';part='37460-2B006';compactPart='374602B006';categoryId='177698';usd='62.35';shipping='7day normal';title='⭐Genuine 374602B006 Alternator Bracket For Accent Veloster Forte Soul 1.6L';partWords='alternator bracket';usStores=@('13135350012','20622051012');auStores=@('/Hyundai/Accent','/Hyundai/Veloster');auTargets=@(@{make='Kia';model='Rio';minYear=2012;maxYear=2019;enginePattern='(?i)(1588cc|1591cc|1.6L).*Petrol'},@{make='Kia';model='Soul';minYear=2012;maxYear=2019;enginePattern='(?i)(1591cc|1.6L).*Petrol'},@{make='Kia';model='Cerato';minYear=2014;maxYear=2018;enginePattern='(?i)(1591cc|1.6L).*Petrol'},@{make='Hyundai';model='Accent';minYear=2012;maxYear=2017;enginePattern='(?i)(1591cc|1.6L).*Petrol'},@{make='Hyundai';model='Veloster';minYear=2012;maxYear=2017;enginePattern='(?i)(1591cc|1.6L).*Petrol'})},
